(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.01+t*0.15)*20 + Math.cos(sy*0.012-t*0.18)*15;
  const w2y = Math.cos(sy*0.009-t*0.12)*18 + Math.sin(sx*0.011+t*0.22)*12;
  const dx = sx + w2x, dy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.85],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.14, 1.3, 0.75],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.11, 2.1, 1.05],
    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*70, 0.055, 2.8, 0.95]
  ];
  let aS=0, iS=0, fS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS += Math.sin(d*f - t*sp)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    fS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.0)*w;
  }
  const tw = 9*0.9;
  const act = aS/tw, inh = iS/tw, fuel = fS/tw;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2
    + Math.sin(dx*0.08+t*1.7)*Math.cos(dy*0.06-t*1.3)*0.15;
  const dist = Math.sqrt((dx-cx)**2+(dy-cy)**2);
  const ang = Math.atan2(dy-cy, dx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = Math.sin(dist*0.03-ang*5+t*0.8)*Math.cos(dist*0.025+ang*2-t*1.6)*0.3;
  const sp3 = Math.sin(ang*7-dist*0.02+t*2.2)*0.15*Math.exp(-dist*0.003);
  const spiral = sp1+sp2+sp3;
  const cross = Math.sin(dx*0.18)*Math.sin(dy*0.18) + Math.sin((dx+dy)*0.13+t)*0.5;
  const cell = Math.tanh(cross*1.5)*0.3;
  const net = Math.sin(dx*0.22+dy*0.1)*Math.cos(dx*0.1-dy*0.22+t*0.7)*0.2;
  const lap = Math.tanh((act - inh*0.65 + fuel*0.4 + bg*0.25 + spiral + net)*2.0);
  const wave = Math.sin(lap*3.5+t*1.2)*0.15;
  const blend = lap*0.6 + cell*0.2 + wave*0.2;
  const v = blend*0.5+0.5;
  const pulse = 0.92+Math.sin(t*0.4)*0.08;
  const pal = [
    [12,8,48],[20,35,95],[18,75,120],[25,130,125],
    [80,170,130],[180,190,80],[220,160,60],
    [210,100,70],[175,55,75],[110,30,65],[50,15,55],[12,8,48]
  ];
  const idx = v*(pal.length-1)*pulse;
  const i = Math.min(Math.max(idx|0,0), pal.length-2);
  const f = idx-i;
  const lum = 0.78+Math.sin(lap*Math.PI)*0.22;
  const edge = Math.abs(lap)>0.65?1.18:Math.abs(lap)>0.4?1.05:0.95;
  const shimmer = 1.0+Math.sin(ang*3+dist*0.08+t*3)*0.06;
  const m = lum*edge*shimmer;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
